mapper.select:
SELECT u.user_id AS userId, u.user_name AS userName, u.user_phone AS userPhone, u.user_email AS userEmail, u.user_role AS userRole, u.user_approved AS userApproved, u.manager_phone_access AS managerPhoneAccess, u.can_allocate AS canAllocate, c.center_name AS centerName, e.expert_name AS expertName, DATE_FORMAT(u.user_created_at, '%Y-%m-%d') AS userCreatedAt FROM users u LEFT JOIN centers c ON u.center_id = c.center_id LEFT JOIN experts e ON u.expert_id = e.expert_id
AND (u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.user_email LIKE CONCAT('%', #{keyword}, '%') OR u.user_phone LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.user_created_at DESC LIMIT #{size} OFFSET #{offset}
